/// Finds the largest prime factor of a given integer `n`.
int largestPrimeFactor(int n) {
  int maxPrime = -1;

  // Divide out factors of 2
  while (n % 2 == 0) {
    maxPrime = 2;
    n ~/= 2;
  }

  // Check for odd factors from 3 to sqrt(n)
  for (int i = 3; i <= sqrt(n).floor(); i += 2) {
    while (n % i == 0) {
      maxPrime = i;
      n ~/= i;
    }
  }

  // If [n] is still greater than 2, it must be prime.
  if (n > 2) {
    return n as int;
  } else {
    return maxPrime ?? throw StateError('No valid primes found');
  }
}

