/// Returns a list of integers from the input that contain only unique digits.
List<int> uniqueDigits(List<int> x) {
  List<int> result = [];

  for (int num in x) {
    // Convert number to string and then set, removing duplicates by nature of sets
    Set<String> digitSet = {num.toString().split('').join()};

    if (digitSet.length == num.toString().length && !result.contains(num)) {
      result.add(num);
    }
  }

  return result;
}

